{
  "name": "ticket_open",
  "description": "Open a new ticket to track a task or bug fix. Returns the ticket path for use with ticket_close and ticket_reopen.",
  "arguments": {
    "type": "object",
    "properties": {
      "client": {
        "description": "Agent client used for this ticket.",
        "type": "string"
      },
      "draft": {
        "description": "Draft slug to seed the ticket workspace.",
        "type": "string"
      },
      "goal": {
        "description": "Goal slug to associate the ticket with.",
        "type": "string"
      },
      "issue": {
        "description": "Existing GitHub issue URL to link instead of creating a new one.",
        "type": "string"
      },
      "llm": {
        "description": "LLM used for this ticket.",
        "type": "string"
      },
      "no_management": {
        "description": "Skip GitHub issue creation and management.",
        "type": "boolean"
      },
      "parent": {
        "description": "Parent ticket slug for nested tickets.",
        "type": "string"
      },
      "prompt": {
        "description": "Full description of the task.",
        "type": "string"
      },
      "title": {
        "description": "Titleized short title (e.g. 'Fix Mcp Descriptions'). Must NOT be a slug or all-caps.",
        "type": "string"
      }
    },
    "required": [
      "title",
      "prompt"
    ]
  }
}

{
  "name": "ticket_close",
  "description": "Close a ticket and record the work summary. When path is omitted, closes the latest open ticket.",
  "arguments": {
    "type": "object",
    "properties": {
      "files": {
        "description": "Files created, updated, or removed during the ticket.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "no_management": {
        "description": "Skip updating the GitHub issue.",
        "type": "boolean"
      },
      "path": {
        "description": "Ticket path as returned by ticket_open (e.g. '26/03/27/FIX-MCP-DESCRIPTIONS'). Omit to close the latest open ticket.",
        "type": "string"
      },
      "summary": {
        "description": "Summary of the work done.",
        "type": "string"
      },
      "title": {
        "description": "Updated title for the ticket.",
        "type": "string"
      }
    },
    "required": [
      "summary"
    ]
  }
}

